  FT["PH-H5530"] = {"id":"PH-H5530","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7040_1991.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Marcelino市","en":"An Act Establishing a High School in the Municipality of San Marcelino, Province of Zambales, to be known as the San Marcelino High School, and Appropriating Funds Therefore","orig":"An Act Establishing a High School in the Municipality of San Marcelino, Province of Zambales, to be known as the San Marcelino High School, and Appropriating Funds Therefore"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7040","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-05-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7040_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5530-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of San Marcelino, Province of Zambales, to be known as the San Marcelino High School."}},{"id":"PH-H5530-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5530-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5530-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p78"};
  FT["PH-H5531"] = {"id":"PH-H5531","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7041_1991.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"要求政府机关定期公布现有空缺职位、为此拨款并为其他目的法案","en":"An Act Requiring Regular Publication of Existing Vacant Positions in Government Offices, Appropriating Funds Therefore, and for Other Purposes","orig":"An Act Requiring Regular Publication of Existing Vacant Positions in Government Offices, Appropriating Funds Therefore, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7041","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-06-05","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7041_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5531-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Policy. – It shall be the policy of the Government to promote efficiency in the allocation of personnel in the civil service, as well as transparency and equal opportunities in the recruitment and hiring of new personnel."}},{"id":"PH-H5531-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Duty of Personnel Officers. – It shall be the duty of all Chief Personnel or Administrative Officers of all branches, subdivisions, instrumentalities and agencies of the Government, including government-owned or controlled corporations with original charters, and local government units, to post in three (3) conspicuous places of their offices for a period of ten (10) days a complete list of all existing vacant positions in their respective offices which are authorized to be filled, and to transmit a copy of such list and the corresponding qualification standards to the Civil Service Commission not later than the tenth day of every month. Vacant positions shall not be filled until after publication: provided, however, that vacant unfilled positions that are:\na) primarily confidential;\nb) policy-determining;\nc) highly technical;\nd) coterminous with that of the appointing authority, or\ne) limited to the duration of a particular project shall be excluded from the list required under this Law."}},{"id":"PH-H5531-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Publication of Vacancies. – The Chairman and members of the Civil Service Commission shall publish once every quarter a complete list of all the existing vacant positions in the Government throughout the country, including the qualification standards required for each position and, thereafter, certify under oath to the completion of publication. Copies of such publication shall be sold at cost to the public and distributed free of charge to the various personnel offices of the government where they shall be available for inspection by the public: provided, that said publication shall be posted by the Chief Personnel or Administrative Officer of all local government units in at least three (3) public and conspicuous places in their respective municipalities and provinces: provided, further, that any vacant position published therein shall be open to any qualified person who does not necessarily belong to the same office with the vacancy or who occupies a position next-in rank to the vacancy: provided, finally, that the Civil Service Commission shall not act on any appointment to fill up a vacant position unless the same has been reported to and published by the Commission."}},{"id":"PH-H5531-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Penalties. – a) Any violation of Sections 2 and or 3 of this Act and its implementing rules and regulations shall subject the official concerned to public censure without prejudice to the withholding of his salary pending compliance with the requirements as provided in this Act.\nb) Any repeated and willful violation of Sections 2 and/or 3 of this Act and it's implementing rules and regulations shall subject the official concerned to criminal prosecution and, upon conviction, suffer the penalty of imprisonment of two (2) years and/or a fine of not less than Five Thousand pesos (P5,000.00) nor more than Ten thousand pesos (P10,000.00), at the discretion of the court."}},{"id":"PH-H5531-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Jurisdiction. – The Civil Service Commission shall have original and exclusive jurisdiction to investigate and recommend for prosecution all cases of violation of this Act: provided, however, that in case the violation is alleged to have been committed by the Chairman and/or any of the Commissioners of the Civil Service Commission, the Ombudsman shall have original and exclusive jurisdiction over the investigation and prosecution of said alleged violation."}},{"id":"PH-H5531-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Implementing Rules. – The Civil Service Commission shall issue the rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H5531-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Existing Laws. – Without prejudice to the provisions of existing laws requiring the posting or disclosure of matters of public interest, the provisions of this Act shall not apply during any period when there is a ban on hiring."}},{"id":"PH-H5531-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Appropriation. – The amount necessary for the effective implementation of this at shall be charged against the appropriations for the Civil Service Commission under the current General Appropriations Act. Thereafter, such amount as may be necessary for the continuous implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H5531-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing Clause. – All laws, decrees, orders, rules and regulations or parts thereof inconsistent with this Act or the rules and regulations promulgated pursuant thereto are hereby repealed or amended accordingly."}},{"id":"PH-H5531-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Separability Clause. – If any provision of this Act is declared unconstitutional or inoperative, the other provisions not so declared shall remain in force and effect."}},{"id":"PH-H5531-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after publication in any newspaper of general circulation."}}],"pack":"ph-p78","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring Regular Publication of Existing Vacant Positions in Government Offices, Appropriating Funds Therefore, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
